import 'dart:convert';
import 'dart:io';
import 'dart:math';

/// Creates fresh, ignored local secrets. Never overwrites an existing secret.
void main(List<String> args) {
  final root = File.fromUri(Platform.script).parent.parent;
  final random = Random.secure();
  String secret() =>
      base64Url.encode(List.generate(48, (_) => random.nextInt(256)));
  final passwords = File(
    '${root.path}/batchbeacon_server/config/passwords.yaml',
  );
  if (!passwords.existsSync()) {
    final content = StringBuffer(
      '# Local secrets generated by scripts/setup.dart. Never commit.\n',
    );
    for (final mode in ['development', 'test']) {
      content.writeln('$mode:');
      for (final key in [
        'database',
        'serviceSecret',
        'emailSecretHashPepper',
        'jwtHmacSha512PrivateKey',
        'jwtRefreshTokenHashPepper',
      ]) {
        content.writeln('  $key: "${secret()}"');
      }
    }
    passwords.parent.createSync(recursive: true);
    passwords.writeAsStringSync(content.toString());
    stdout.writeln('Created ignored development/test passwords.yaml.');
  } else {
    stdout.writeln('Preserved existing passwords.yaml.');
  }
  if (args.contains('--clean-admin')) {
    for (final role in ['platform', 'hospital']) {
      final file = File(
        '${root.path}/batchbeacon_server/.serverpod/clean_${role}_password',
      );
      if (!file.existsSync()) {
        file.parent.createSync(recursive: true);
        file.writeAsStringSync(secret());
      }
      stdout.writeln('Clean $role admin password file: ${file.path}');
    }
  }
  stdout.writeln(
    'No accounts or operational records are created until the server starts.',
  );
}
